def build_plan():
    plan = []

    # === CENTRAL POWER HUB ===
    # Place two coal power plants in the center-top area
    # and distribute power via vertical + horizontal wires

    cx, cy = 60, 20  # central x, power row y

    # Two coal plants flanking center
    plan.append((Tool.COALPOWER, cx - 10, cy))
    plan.append((Tool.COALPOWER, cx + 10, cy))

    # Horizontal wire spine connecting both plants and extending outward
    for x in range(cx - 10, cx + 15):
        plan.append((Tool.WIRE, x, cy))

    # === THREE NEIGHBORHOODS arranged vertically ===

    # --- NEIGHBORHOOD A: Left cluster (x=20, rows 28-60) ---
    ax, ay = 20, 35
    # Vertical wire from power line down to neighborhood
    for y in range(cy + 1, ay + 1):
        plan.append((Tool.WIRE, cx - 10, y))
    # Horizontal wire to neighborhood
    for x in range(ax - 2, cx - 9):
        plan.append((Tool.WIRE, x, ay))

    # Road grid for neighborhood A: 3 horizontal roads
    for road_y in [ay - 1, ay + 3, ay + 7]:
        for x in range(ax - 4, ax + 16):
            plan.append((Tool.ROAD, x, road_y))
    # 2 vertical roads connecting horizontal roads
    for road_x in [ax - 4, ax + 5, ax + 14]:
        for y in range(ay - 1, ay + 8):
            plan.append((Tool.ROAD, road_x, y))

    # Zones in grid pattern for neighborhood A
    zone_cycle_a = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
    k = 0
    for row_y in [ay + 1, ay + 5]:
        for col_x in [ax - 2, ax + 2, ax + 8, ax + 12]:
            plan.append((zone_cycle_a[k % len(zone_cycle_a)], col_x, row_y))
            k += 1

    # Fire/police for A
    plan.append((Tool.FIRESTATION, ax - 4, ay - 4))
    plan.append((Tool.POLICESTATION, ax + 2, ay - 4))

    # --- NEIGHBORHOOD B: Center cluster (x=60, rows 30-65) ---
    bx, by = 60, 40
    # Vertical wire from power line down
    for y in range(cy + 1, by + 1):
        plan.append((Tool.WIRE, cx, y))

    # Road grid for neighborhood B
    for road_y in [by - 1, by + 3, by + 7, by + 11]:
        for x in range(bx - 8, bx + 12):
            plan.append((Tool.ROAD, x, road_y))
    for road_x in [bx - 8, bx - 2, bx + 4, bx + 10]:
        for y in range(by - 1, by + 12):
            plan.append((Tool.ROAD, road_x, y))

    # Larger zone grid for B - more commercial and industrial mix
    zone_cycle_b = [Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL]
    k = 0
    for row_y in [by + 1, by + 5, by + 9]:
        for col_x in [bx - 5, bx + 1, bx + 7]:
            plan.append((zone_cycle_b[k % len(zone_cycle_b)], col_x, row_y))
            k += 1

    plan.append((Tool.FIRESTATION, bx - 8, by - 4))
    plan.append((Tool.POLICESTATION, bx + 4, by - 4))

    # --- NEIGHBORHOOD C: Right cluster (x=95, rows 35-65) ---
    rx, ry = 95, 45
    # Vertical wire from power line down
    for y in range(cy + 1, ry + 1):
        plan.append((Tool.WIRE, cx + 10, y))
    # Horizontal wire to right neighborhood
    for x in range(cx + 11, rx + 3):
        plan.append((Tool.WIRE, x, ry))

    # Road grid for neighborhood C
    for road_y in [ry - 1, ry + 3, ry + 7]:
        for x in range(rx - 8, rx + 10):
            plan.append((Tool.ROAD, x, road_y))
    for road_x in [rx - 8, rx - 2, rx + 4, rx + 9]:
        for y in range(ry - 1, ry + 8):
            plan.append((Tool.ROAD, road_x, y))

    zone_cycle_c = [Tool.INDUSTRIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL]
    k = 0
    for row_y in [ry + 1, ry + 5]:
        for col_x in [rx - 5, rx + 1, rx + 7]:
            plan.append((zone_cycle_c[k % len(zone_cycle_c)], col_x, row_y))
            k += 1

    plan.append((Tool.FIRESTATION, rx + 6, ry - 4))
    plan.append((Tool.POLICESTATION, rx - 5, ry - 4))

    # === Connect all three neighborhoods with roads ===
    # Horizontal connector road at y=62
    for x in range(ax - 4, rx + 10):
        plan.append((Tool.ROAD, x, by + 12))
    # Vertical roads connecting neighborhoods to main connector
    for y in range(ay + 8, by + 13):
        plan.append((Tool.ROAD, ax - 4, y))
    for y in range(by + 12, ry + 8):
        plan.append((Tool.ROAD, rx - 8, y))

    # === Lower extension: small southern neighborhood ===
    sx, sy = 40, 75
    # Wire from neighborhood B connector down
    for y in range(by + 3, sy + 1):
        plan.append((Tool.WIRE, bx - 2, y))
    for x in range(sx - 2, bx - 1):
        plan.append((Tool.WIRE, x, sy))

    for road_y in [sy - 1, sy + 3, sy + 7]:
        for x in range(sx - 4, sx + 13):
            plan.append((Tool.ROAD, x, road_y))
    for road_x in [sx - 4, sx + 3, sx + 12]:
        for y in range(sy - 1, sy + 8):
            plan.append((Tool.ROAD, road_x, y))

    zone_cycle_s = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
    k = 0
    for row_y in [sy + 1, sy + 5]:
        for col_x in [sx - 1, sx + 6]:
            plan.append((zone_cycle_s[k % len(zone_cycle_s)], col_x, row_y))
            k += 1

    plan.append((Tool.FIRESTATION, sx + 10, sy - 4))

    return plan


