def act(obs, state):
    """
    Combined policy: 
    - Three neighborhoods arranged horizontally (from Parent A)
    - Nuclear power plants for better coverage (from Parent A)
    - Better wire/road connectivity ensuring zones are powered (fix from Parent A issues)
    - Compact cluster design with proper road+wire access (from Parent B)
    - Services spread appropriately
    """
    if "plan" not in state:
        plan = []

        # Three neighborhoods, each self-contained with nuclear power
        # Layout: power plant -> wire to road spine -> zones on both sides

        neighborhoods = [
            (20, 30),   # left-top
            (60, 30),   # center-top
            (100, 30),  # right-top
            (20, 70),   # left-bottom
            (60, 70),   # center-bottom
            (100, 70),  # right-bottom
        ]

        for idx, (cx, cy) in enumerate(neighborhoods):
            # Nuclear power plant at center
            plan.append((Tool.NUCLEARPOWER, cx, cy))

            # Wire from plant outward in both directions along horizontal
            for dx in range(-5, 10):
                plan.append((Tool.WIRE, cx + dx, cy))

            # Vertical wire spine for power distribution
            for dy in range(-12, 13):
                plan.append((Tool.WIRE, cx + 2, cy + dy))

            # Vertical road at cx+3 (adjacent to wire, zones can access both)
            road_x = cx + 3
            for dy in range(-12, 13):
                plan.append((Tool.ROAD, road_x, cy + dy))

            # Horizontal road cross at cy
            for dx in range(-4, 8):
                plan.append((Tool.ROAD, cx + dx, cy + 1))

            # Zones on left side of road (center at road_x - 3)
            for dy in range(-10, 11, 4):
                zone_y = cy + dy
                if zone_y < 3 or zone_y > 96:
                    continue
                plan.append((Tool.RESIDENTIAL, road_x - 3, zone_y))

            # Zones on right side of road (center at road_x + 3)
            for dy in range(-10, 11, 4):
                zone_y = cy + dy
                if zone_y < 3 or zone_y > 96:
                    continue
                mod = (dy // 4) % 3
                if mod == 0:
                    plan.append((Tool.COMMERCIAL, road_x + 3, zone_y))
                elif mod == 1:
                    plan.append((Tool.INDUSTRIAL, road_x + 3, zone_y))
                else:
                    plan.append((Tool.RESIDENTIAL, road_x + 3, zone_y))

            # Extra residential column further left
            for dy in range(-8, 9, 4):
                zone_y = cy + dy
                if zone_y < 3 or zone_y > 96:
                    continue
                plan.append((Tool.RESIDENTIAL, road_x - 7, zone_y))

            # Fire and police station for each neighborhood
            plan.append((Tool.FIRESTATION, cx - 3, cy - 10))
            plan.append((Tool.POLICESTATION, cx + 6, cy - 10))

        # Horizontal connecting road at y=50 (middle of map)
        for x in range(2, 118):
            plan.append((Tool.ROAD, x, 50))

        # Wire along y=51 connecting power plants
        for x in range(2, 118):
            plan.append((Tool.WIRE, x, 51))

        # Wire along y=49 as well for redundancy
        for x in range(2, 118):
            plan.append((Tool.WIRE, x, 49))

        # Connect vertical roads of each neighborhood to the horizontal spine
        for cx, cy in neighborhoods:
            road_x = cx + 3
            if cy < 50:
                for y in range(cy + 1, 50):
                    plan.append((Tool.ROAD, road_x, y))
            else:
                for y in range(50, cy + 1):
                    plan.append((Tool.ROAD, road_x, y))

        # Extra commercial zones along the horizontal spine
        for x in range(10, 110, 10):
            if 3 <= 50 <= 96:
                plan.append((Tool.COMMERCIAL, x, 45))
                plan.append((Tool.COMMERCIAL, x, 55))

        # Stadiums for population boost
        plan.append((Tool.STADIUM, 40, 50))
        plan.append((Tool.STADIUM, 80, 50))

        # Additional wire connections from neighborhood plants to horizontal spine
        for cx, cy in neighborhoods:
            # Vertical wire from plant down/up to the spine
            road_x = cx + 3
            if cy < 50:
                for y in range(cy, 51):
                    plan.append((Tool.WIRE, road_x - 1, y))
            else:
                for y in range(49, cy + 1):
                    plan.append((Tool.WIRE, road_x - 1, y))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]
    if i >= len(plan):
        return None
    state["i"] = i + 1
    tool, x, y = plan[i]
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

def build_plan():
    # Build two neighborhoods: one centered at (40, 50), one at (80, 50)
    # Each neighborhood has a coal plant, wire spine, road, and mixed zones (R/C/I)
    plan = []

    for (cx, cy) in [(40, 50), (80, 50)]:
        # Coal power plant to the left of the spine
        plan.append((Tool.COALPOWER, cx - 6, cy))
        # Wire from power plant to spine
        for dx in range(-5, 1):
            plan.append((Tool.WIRE, cx + dx, cy))
        # Vertical wire spine at cx, road at cx+1
        for dy in range(-15, 16):
            plan.append((Tool.WIRE, cx, cy + dy))
            plan.append((Tool.ROAD, cx + 1, cy + dy))
        # Also connect wire from plant up and down
        for dy in range(-15, 16):
            plan.append((Tool.WIRE, cx - 5, cy + dy))
            plan.append((Tool.WIRE, cx - 4, cy + dy))

        # Mixed zones: Residential left, Commercial right top, Industrial right bottom
        for i, dy in enumerate(range(-15, 16, 3)):
            # Left side: alternating R and C
            if i % 3 == 0:
                plan.append((Tool.RESIDENTIAL, cx - 3, cy + dy))
            elif i % 3 == 1:
                plan.append((Tool.COMMERCIAL, cx - 3, cy + dy))
            else:
                plan.append((Tool.RESIDENTIAL, cx - 3, cy + dy))
            # Right side: alternating R and I
            if i % 3 == 0:
                plan.append((Tool.RESIDENTIAL, cx + 4, cy + dy))
            elif i % 3 == 1:
                plan.append((Tool.INDUSTRIAL, cx + 4, cy + dy))
            else:
                plan.append((Tool.RESIDENTIAL, cx + 4, cy + dy))

    # Connect the two neighborhoods with a horizontal road at y=50
    for x in range(43, 77):
        plan.append((Tool.ROAD, x, 50))

    return plan

