def act(obs, state):
    """
    Two neighborhoods side by side, each with coal power plant,
    horizontal wire spine + vertical roads, zones above and below.
    Different layout: wider zone coverage, more commercial/industrial mix,
    services placed more strategically, road grid instead of single road.
    """
    if "plan" not in state:
