def build_plan():
    plan = []

    # Good R/C/I balance cycle from Parent A
    zone_cycle = [
        Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL,
        Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
        Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.RESIDENTIAL,
    ]

    def add_cluster(cx, cy, zone_offset=0, power_tool=Tool.COALPOWER):
        """
        Combines Parent A's multi-row zone layout with Parent B's bounds checking.
        Wire spine + roads above/below + 3 rows of zones on each side.
        """
        # Power plant at center
        plan.append((power_tool, cx, cy))

        # Horizontal wire spine at cy
        for dx in range(-13, 14):
            nx = cx + dx
            if 0 <= nx <= 119 and (dx < -1 or dx > 1):  # avoid overwriting plant center
                plan.append((Tool.WIRE, nx, cy))

        # Roads flanking the wire spine
        for dx in range(-13, 14):
            nx = cx + dx
            if 0 <= nx <= 119:
                if cy - 1 >= 0:
                    plan.append((Tool.ROAD, nx, cy - 1))
                if cy + 1 <= 99:
                    plan.append((Tool.ROAD, nx, cy + 1))

        # Row 1 zones: cy-3 and cy+3
        k = 0
        for dx in range(-12, 13, 3):
            zx = cx + dx
            if 3 <= zx <= 116:
                if 3 <= cy - 3 <= 96:
                    plan.append((zone_cycle[(k + zone_offset) % len(zone_cycle)], zx, cy - 3))
                if 3 <= cy + 3 <= 96:
                    plan.append((zone_cycle[(k + zone_offset + 3) % len(zone_cycle)], zx, cy + 3))
                k += 1

