            zx = cx + dx
            if 3 <= zx <= 116:
                if 3 <= cy - 9 <= 96:
                    plan.append((zone_cycle[(k + zone_offset + 2) % len(zone_cycle)], zx, cy - 9))
                if 3 <= cy + 9 <= 96:
                    plan.append((zone_cycle[(k + zone_offset + 5) % len(zone_cycle)], zx, cy + 9))
