def build_plan():
    plan = []

    # Strategy: Take Parent B's proven neighborhood structure (3 neighborhoods, 
    # vertical arrangement) but enhance with Parent A's ideas of:
    # - Better power connectivity (wires alongside roads)
    # - More zones per neighborhood
    # - Cross-connecting infrastructure
    # - Services near zones

    # === NEIGHBORHOOD 1: TOP-LEFT (centered around x=30, y=18) ===
    tx, ty = 30, 18

    # Coal power plant to the left
    plan.append((Tool.COALPOWER, tx - 5, ty + 2))

    # Horizontal wire from plant to right edge of neighborhood
    for dx in range(-4, 22):
        nx = tx + dx
        if 0 <= nx < WORLD_W:
            plan.append((Tool.WIRE, nx, ty + 2))

    # Horizontal road just below wire
    for dx in range(-4, 22):
        nx = tx + dx
        if 0 <= nx < WORLD_W:
            plan.append((Tool.ROAD, nx, ty + 3))

    # Vertical road for access
    for dy in range(-12, 15):
        ny = ty + dy
        if 0 <= ny < WORLD_H:
            plan.append((Tool.ROAD, tx + 9, ny))

    # Zones ABOVE spine (rows at ty, ty-3, ty-6)
    zone_seq = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL]
    for i, dx in enumerate(range(0, 18, 3)):
        zx = tx + dx
        if 3 <= zx <= WORLD_W - 4:
            plan.append((zone_seq[i % len(zone_seq)], zx, ty))
            plan.append((Tool.WIRE, zx, ty + 1))  # connect to spine wire
            if ty - 3 >= 3:
                plan.append((zone_seq[(i+1) % len(zone_seq)], zx, ty - 3))
                plan.append((Tool.WIRE, zx, ty - 2))

    # Zones BELOW spine (rows at ty+6, ty+9)
    zone_seq2 = [Tool.COMMERCIAL, Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]
    for i, dx in enumerate(range(0, 18, 3)):
        zx = tx + dx
        if 3 <= zx <= WORLD_W - 4:
            plan.append((zone_seq2[i % len(zone_seq2)], zx, ty + 6))
            plan.append((Tool.WIRE, zx, ty + 5))
            if ty + 9 <= WORLD_H - 4:
                plan.append((zone_seq2[(i+2) % len(zone_seq2)], zx, ty + 9))
                plan.append((Tool.WIRE, zx, ty + 8))

    # Services
    plan.append((Tool.FIRESTATION, tx + 18, ty))
    plan.append((Tool.POLICESTATION, tx + 18, ty + 6))

    # === NEIGHBORHOOD 2: MIDDLE-RIGHT (centered around x=70, y=48) ===
    mx, my = 70, 48

    # Coal power plant to the right
    plan.append((Tool.COALPOWER, mx + 22, my + 2))

    # Horizontal wire
    for dx in range(-5, 23):
        nx = mx + dx
        if 0 <= nx < WORLD_W:
            plan.append((Tool.WIRE, nx, my + 2))

    # Horizontal road
    for dx in range(-5, 23):
        nx = mx + dx
        if 0 <= nx < WORLD_W:
            plan.append((Tool.ROAD, nx, my + 3))

    # Vertical road for access
    for dy in range(-12, 15):
        ny = my + dy
        if 0 <= ny < WORLD_H:
            plan.append((Tool.ROAD, mx + 9, ny))

    # Connect top neighborhood to middle via road
    for y in range(ty + 3, my + 3):
        if 0 <= y < WORLD_H:
            plan.append((Tool.ROAD, tx + 9, y))
    # Wire connection between neighborhoods
    for y in range(ty + 3, my + 2):
        if 0 <= y < WORLD_H:
            plan.append((Tool.WIRE, tx + 9, y))

    # Zones ABOVE spine
    for i, dx in enumerate(range(0, 21, 3)):
        zx = mx + dx
        if 3 <= zx <= WORLD_W - 4:
            plan.append((zone_seq[(i+2) % len(zone_seq)], zx, my))
            plan.append((Tool.WIRE, zx, my + 1))
            if my - 3 >= 3:
                plan.append((zone_seq[(i+3) % len(zone_seq)], zx, my - 3))
                plan.append((Tool.WIRE, zx, my - 2))

    # Zones BELOW spine
    for i, dx in enumerate(range(0, 21, 3)):
        zx = mx + dx
        if 3 <= zx <= WORLD_W - 4:
            plan.append((zone_seq2[(i+1) % len(zone_seq2)], zx, my + 6))
            plan.append((Tool.WIRE, zx, my + 5))
            if my + 9 <= WORLD_H - 4:
                plan.append((zone_seq2[(i+3) % len(zone_seq2)], zx, my + 9))
                plan.append((Tool.WIRE, zx, my + 8))

    # Services
    plan.append((Tool.FIRESTATION, mx - 3, my - 3))
    plan.append((Tool.POLICESTATION, mx + 3, my - 3))

    # === NEIGHBORHOOD 3: BOTTOM-LEFT (centered around x=25, y=78) ===
    bx, by = 25, 78

    # Coal power plant to the left
    plan.append((Tool.COALPOWER, bx - 5, by + 2))

    # Horizontal wire
    for dx in range(-4, 22):
        nx = bx + dx
        if 0 <= nx < WORLD_W:
            plan.append((Tool.WIRE, nx, by + 2))

    # Horizontal road
    for dx in range(-4, 22):
        nx = bx + dx
        if 0 <= nx < WORLD_W:
            plan.append((Tool.ROAD, nx, by + 3))

    # Vertical road
    for dy in range(-12, 12):
        ny = by + dy
        if 0 <= ny < WORLD_H:
            plan.append((Tool.ROAD, bx + 9, ny))

    # Connect middle to bottom via road and wire
    for y in range(my + 3, by + 3):
        if 0 <= y < WORLD_H:
            plan.append((Tool.ROAD, mx + 6, y))
            plan.append((Tool.WIRE, mx + 6, y))

    # Zones ABOVE spine
    for i, dx in enumerate(range(0, 18, 3)):
        zx = bx + dx
        if 3 <= zx <= WORLD_W - 4:
            plan.append((zone_seq[(i+4) % len(zone_seq)], zx, by))
            plan.append((Tool.WIRE, zx, by + 1))
            if by - 3 >= 3:
                plan.append((zone_seq[(i+5) % len(zone_seq)], zx, by - 3))
                plan.append((Tool.WIRE, zx, by - 2))

    # Zones BELOW spine
    for i, dx in enumerate(range(0, 18, 3)):
        zx = bx + dx
        if 3 <= zx <= WORLD_W - 4 and by + 9 <= WORLD_H - 4:
            plan.append((zone_seq2[(i+2) % len(zone_seq2)], zx, by + 6))
            plan.append((Tool.WIRE, zx, by + 5))
            plan.append((zone_seq2[(i+4) % len(zone_seq2)], zx, by + 9))
            plan.append((Tool.WIRE, zx, by + 8))

    # Services
    plan.append((Tool.FIRESTATION, bx + 18, by))
    plan.append((Tool.POLICESTATION, bx + 18, by + 6))
    plan.append((Tool.STADIUM, bx + 15, by + 9))

    # === CROSS-MAP CONNECTING ROAD ===
    # Horizontal road at y=48+3=51 area connecting neighborhoods
    for x in range(1, WORLD_W - 1):
        plan.append((Tool.ROAD, x, 51))

    # Extra coal plant in center for power redundancy
    plan.append((Tool.COALPOWER, 5, 51))
    plan.append((Tool.COALPOWER, 113, 48))

    # Wire along the central road to distribute power
    for x in range(1, WORLD_W - 1):
        plan.append((Tool.WIRE, x, 50))

    # Connect all 3 neighborhood power spines to central wire at y=50
    for (nx, ny) in [(tx, ty + 2), (mx, my + 2), (bx, by + 2)]:
        if ny < 50:
            for y in range(ny, 51):
                if 0 <= y < WORLD_H:
                    plan.append((Tool.WIRE, nx, y))
        else:
            for y in range(50, ny + 1):
                if 0 <= y < WORLD_H:
                    plan.append((Tool.WIRE, nx, y))

    # Stadium near center for boost
    plan.append((Tool.STADIUM, 55, 51))

    return plan


def act(obs, state):
    if "plan" not in state:
        state["plan"] = build_plan()
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i >= len(plan):
        return None

    state["i"] = i + 1
    tool, x, y = plan[i]

    # Clamp coordinates
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))

    return (tool, x, y)

def build_plan():
    plan = []

    # Different approach: linear strip layout along horizontal bands
    # 3 horizontal bands, each with power plant + dense zone rows + roads/wires
    # Focus on denser commercial/industrial mix for higher pop density
    # Use nuclear for top band, coal for others
    # Bands at y=20, y=50, y=80

    zone_mix_res_heavy = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                          Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.RESIDENTIAL,
                          Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.RESIDENTIAL]
    zone_mix_com_heavy = [Tool.COMMERCIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL,
                          Tool.INDUSTRIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL,
                          Tool.COMMERCIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL]
    zone_mix_ind_heavy = [Tool.INDUSTRIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL,
                          Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL,
                          Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL]

    def add_strip(cy, power_tool, zm_above, zm_below, power_x=10):
        # Power plant on left side
        plan.append((power_tool, power_x, cy))

        # Full-width wire spine at cy
        for x in range(0, 120):
            plan.append((Tool.WIRE, x, cy))

        # Roads flanking the wire spine
        for x in range(0, 120):
            if cy - 1 >= 0:
                plan.append((Tool.ROAD, x, cy - 1))
            if cy + 1 <= 99:
                plan.append((Tool.ROAD, x, cy + 1))

        # Zones above: at cy-3, cy-6 (two rows of zones)
        for i, x in enumerate(range(3, 117, 3)):
            if 3 <= cy - 3 <= 96:
                plan.append((zm_above[i % len(zm_above)], x, cy - 3))
            if 3 <= cy - 7 <= 96:
                plan.append((zm_below[i % len(zm_below)], x, cy - 7))

        # Zones below: at cy+3, cy+6
        for i, x in enumerate(range(3, 117, 3)):
            if 3 <= cy + 3 <= 96:
                plan.append((zm_below[i % len(zm_below)], x, cy + 3))
            if 3 <= cy + 7 <= 96:
                plan.append((zm_above[i % len(zm_above)], x, cy + 7))

        # Additional road at cy-5 and cy+5 for zone access
        for x in range(0, 120):
            if cy - 5 >= 0:
                plan.append((Tool.ROAD, x, cy - 5))
            if cy + 5 <= 99:
                plan.append((Tool.ROAD, x, cy + 5))

        # Wire row at cy-10 and cy+10 for outer zones
        for x in range(0, 120):
            if cy - 10 >= 0:
                plan.append((Tool.WIRE, x, cy - 10))
            if cy + 10 <= 99:
                plan.append((Tool.WIRE, x, cy + 10))

        # Zones at cy-12 and cy+12
        for i, x in enumerate(range(3, 117, 3)):
            if 3 <= cy - 12 <= 96:
                plan.append((zm_above[i % len(zm_above)], x, cy - 12))
            if 3 <= cy + 12 <= 96:
                plan.append((zm_below[i % len(zm_below)], x, cy + 12))

        # Road at cy-11 and cy+11
        for x in range(0, 120):
            if cy - 11 >= 0:
                plan.append((Tool.ROAD, x, cy - 11))
            if cy + 11 <= 99:
                plan.append((Tool.ROAD, x, cy + 11))

        # Services every 20 tiles along strip
        for sx in range(10, 120, 25):
            if 0 <= sx <= 116:
                if 3 <= cy - 3 <= 96:
                    plan.append((Tool.FIRESTATION, sx, cy - 3))
                if 3 <= cy + 3 <= 96:
                    plan.append((Tool.POLICESTATION, sx, cy + 3))

    # Three horizontal strips
    # Top strip: y=18, nuclear power
    add_strip(18, Tool.NUCLEARPOWER, zone_mix_res_heavy, zone_mix_com_heavy, power_x=10)

    # Middle strip: y=50, coal power
    add_strip(50, Tool.COALPOWER, zone_mix_com_heavy, zone_mix_ind_heavy, power_x=10)

    # Bottom strip: y=82, coal power
    add_strip(82, Tool.COALPOWER, zone_mix_ind_heavy, zone_mix_res_heavy, power_x=10)

    # Connect strips with vertical wires on left and right sides
    for y in range(19, 50):
        plan.append((Tool.WIRE, 0, y))
        plan.append((Tool.WIRE, 119, y))
        plan.append((Tool.ROAD, 1, y))
        plan.append((Tool.ROAD, 118, y))

    for y in range(51, 82):
        plan.append((Tool.WIRE, 0, y))
        plan.append((Tool.WIRE, 119, y))
        plan.append((Tool.ROAD, 1, y))
        plan.append((Tool.ROAD, 118, y))

    # Connect strips with vertical wires in middle too
    for y in range(19, 50):
        plan.append((Tool.WIRE, 60, y))
        plan.append((Tool.ROAD, 61, y))
        plan.append((Tool.ROAD, 59, y))

    for y in range(51, 82):
        plan.append((Tool.WIRE, 60, y))
        plan.append((Tool.ROAD, 61, y))
        plan.append((Tool.ROAD, 59, y))

    # Second coal plant for middle strip on right side
    plan.append((Tool.COALPOWER, 110, 50))

    # Second nuclear for top strip backup
    plan.append((Tool.NUCLEARPOWER, 110, 18))

    # Stadium in center for happiness bonus
    plan.append((Tool.STADIUM, 60, 50))

    # Seaport at bottom-right
    plan.append((Tool.SEAPORT, 112, 92))
    for x in range(100, 119):
        plan.append((Tool.WIRE, x, 92))
    for y in range(83, 93):
        plan.append((Tool.WIRE, 119, y))

    # Parks scattered for land value
    for px, py in [(30, 18), (90, 18), (30, 50), (90, 50), (30, 82), (90, 82),
                   (60, 35), (60, 65), (5, 35), (5, 65), (115, 35), (115, 65)]:
        plan.append((Tool.PARK, max(0, min(119, px)), max(0, min(99, py))))

    # Extra fire/police stations along connectors
    for sy in [35, 65]:
        plan.append((Tool.FIRESTATION, 3, sy))
        plan.append((Tool.POLICESTATION, 116, sy))

    # Additional airports for city score
    plan.append((Tool.AIRPORT, 55, 92))
    for x in range(50, 65):
        plan.append((Tool.WIRE, x, 92))
    for y in range(83, 93):
        plan.append((Tool.WIRE, 60, y))

    return plan


def act(obs, state):
    if "plan" not in state:
