def build_plan():
    plan = []

    # More balanced zone mix with higher commercial ratio
    zone_cycle = [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.COMMERCIAL,
                  Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                  Tool.RESIDENTIAL, Tool.INDUSTRIAL, Tool.COMMERCIAL,
                  Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL]

    def add_cluster(cx, cy, zone_offset=0):
        # Two coal power plants side by side for more power coverage
        plan.append((Tool.COALPOWER, cx - 2, cy))
        plan.append((Tool.COALPOWER, cx + 2, cy))

        # Horizontal wire spine
        for dx in range(-14, 15):
            nx = cx + dx
            if 0 <= nx <= 119:
                plan.append((Tool.WIRE, nx, cy))

        # Roads above and below wire spine
        for dx in range(-14, 15):
            nx = cx + dx
            if 0 <= nx <= 119:
                if cy + 2 <= 99:
                    plan.append((Tool.ROAD, nx, cy + 2))
                if cy - 2 >= 0:
                    plan.append((Tool.ROAD, nx, cy - 2))

        # Row 1 zones above and below
        k = 0
        for dx in range(-12, 13, 3):
            zx = cx + dx
            if 3 <= zx <= 116:
                if 3 <= cy - 5 <= 96:
                    plan.append((zone_cycle[(k + zone_offset) % len(zone_cycle)], zx, cy - 5))
                if 3 <= cy + 5 <= 96:
                    plan.append((zone_cycle[(k + zone_offset + 4) % len(zone_cycle)], zx, cy + 5))
                k += 1

        # Wire + road for row 2
        for dx in range(-14, 15):
            nx = cx + dx
            if 0 <= nx <= 119:
                if cy - 9 >= 0:
                    plan.append((Tool.WIRE, nx, cy - 9))
                if cy - 8 >= 0:
                    plan.append((Tool.ROAD, nx, cy - 8))
                if cy + 9 <= 99:
                    plan.append((Tool.WIRE, nx, cy + 9))
                if cy + 8 <= 99:
                    plan.append((Tool.ROAD, nx, cy + 8))

        # Row 2 zones
        k = 0
        for dx in range(-12, 13, 3):
            zx = cx + dx
            if 3 <= zx <= 116:
                if 3 <= cy - 12 <= 96:
                    plan.append((zone_cycle[(k + zone_offset + 2) % len(zone_cycle)], zx, cy - 12))
                if 3 <= cy + 12 <= 96:
                    plan.append((zone_cycle[(k + zone_offset + 6) % len(zone_cycle)], zx, cy + 12))
                k += 1

        # Vertical wire for lateral reach
        for dy in range(-13, 14):
            if 0 <= cy + dy <= 99:
                plan.append((Tool.WIRE, cx, cy + dy))

        # Fire and police stations spread out
        sx1 = min(cx + 12, 116)
        sx2 = max(cx - 12, 3)
        if 3 <= cy - 5 <= 96:
            plan.append((Tool.FIRESTATION, sx1, cy - 5))
        if 3 <= cy + 5 <= 96:
            plan.append((Tool.POLICESTATION, sx2, cy + 5))

    # === MAIN CENTER CLUSTER (moved to true center) ===
    add_cluster(60, 50, zone_offset=0)

    # === TOP-LEFT CLUSTER ===
    add_cluster(25, 20, zone_offset=3)

    # === TOP-RIGHT CLUSTER ===
    add_cluster(95, 20, zone_offset=6)

    # === BOTTOM-LEFT CLUSTER ===
    add_cluster(25, 80, zone_offset=9)

    # === BOTTOM-RIGHT CLUSTER ===
    add_cluster(95, 80, zone_offset=0)

    # === Cross connectors: vertical ===
    for y in range(22, 49):
        plan.append((Tool.ROAD, 60, y))
        plan.append((Tool.WIRE, 61, y))

    for y in range(51, 79):
        plan.append((Tool.ROAD, 60, y))
        plan.append((Tool.WIRE, 61, y))

    # === Horizontal connectors ===
    for x in range(27, 59):
        plan.append((Tool.ROAD, x, 50))
        plan.append((Tool.WIRE, x, 49))

    for x in range(61, 93):
        plan.append((Tool.ROAD, x, 50))
        plan.append((Tool.WIRE, x, 49))

    # Top horizontal connector
    for x in range(27, 93):
        plan.append((Tool.ROAD, x, 20))
        plan.append((Tool.WIRE, x, 21))

    # Bottom horizontal connector
    for x in range(27, 93):
        plan.append((Tool.ROAD, x, 80))
        plan.append((Tool.WIRE, x, 81))

    # Left vertical connector
    for y in range(22, 78):
        plan.append((Tool.ROAD, 25, y))
        plan.append((Tool.WIRE, 24, y))

    # Right vertical connector
    for y in range(22, 78):
        plan.append((Tool.ROAD, 95, y))
        plan.append((Tool.WIRE, 96, y))

    # === Extra coal at intersections ===
    plan.append((Tool.COALPOWER, 25, 50))
    plan.append((Tool.COALPOWER, 95, 50))
    # Wire from mid-connectors
    for dx in range(-5, 6):
        plan.append((Tool.WIRE, 25 + dx, 50))
        plan.append((Tool.WIRE, 95 + dx, 50))

    # === Extra zones along connectors ===
    mid_cycle = [Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                 Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL]
    k = 0
    for y in [35, 65]:
        for x in [40, 60, 80]:
            if 3 <= x <= 116 and 3 <= y <= 96:
                plan.append((mid_cycle[k % len(mid_cycle)], x, y))
                k += 1

    # Roads and wires for mid-connector zones
    for y in [33, 34, 36, 37, 63, 64, 66, 67]:
        for x in range(37, 83):
            if 0 <= x <= 119 and 0 <= y <= 99:
                if y in [34, 36, 64, 66]:
                    plan.append((Tool.WIRE, x, y))
                else:
                    plan.append((Tool.ROAD, x, y))

    # === Services for mid zones ===
    plan.append((Tool.FIRESTATION, 45, 35))
    plan.append((Tool.POLICESTATION, 75, 35))
    plan.append((Tool.FIRESTATION, 45, 65))
    plan.append((Tool.POLICESTATION, 75, 65))

    # === Parks for land value boost ===
    parks = [(10, 10), (110, 10), (10, 90), (110, 90),
             (60, 35), (60, 65), (40, 50), (80, 50)]
    for px, py in parks:
        if 0 <= px <= 119 and 0 <= py <= 99:
            plan.append((Tool.PARK, px, py))

    # === Stadium for large pop growth ===
    plan.append((Tool.STADIUM, 60, 50))

    return plan


def act(obs, state):
    if "plan" not in state:
        state["plan"] = build_plan()
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i >= len(plan):
        return None

    state["i"] = i + 1
    tool, x, y = plan[i]
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)
